window.PSIONIC_DISCIPLINES = [{"group":"Avatar","title":"Crown of Despair","introduction":"\u003cp\u003e\u003cem\u003eAvatar Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou have learned to harvest seeds of despair in a creature\u0027s psyche, wracking it with self-doubt and inaction.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you have advantage on Charisma (Intimidation) checks.\u003c/p\u003e","abilities":[{"title":"Crowned in Sorrow (1-7 psi).","content":"\u003cp\u003eAs an action, one creature you can see within 60 feet of you must make a Charisma saving throw. On a failed save, it takes 1d8 psychic damage per psi point spent, and it can\u0027t take reactions until the start of its next turn. On a successful save, it takes half as much damage.\u003c/p\u003e"},{"title":"Call to Inaction (2 psi; conc., 10 min.).","content":"\u003cp\u003eIf you spend 1 minute conversing with a creature, you can attempt to seed it with overwhelming ennui. At the end of the minute, you can use an action to force the creature to make a Wisdom saving throw. The save automatically succeeds if the target is immune to being charmed. On a failed save, it sits and is incapacitated until your concentration ends. This effect immediately ends if the target or any ally it can see is attacked or takes damage. On a successful save, the creature is unaffected and has no inkling of your attempt to bend its will.\u003c/p\u003e"},{"title":"Visions of Despair (3 psi).","content":"\u003cp\u003eAs an action, you force one creature you can see within 60 feet of you to make a Charisma saving throw. On a failed save, it takes 3d6 psychic damage, and its speed is reduced to 0 until the end of its next turn. On a successful save, it takes half as much damage. You can increase the damage by 1d6 per additional psi point spent on it.\u003c/p\u003e"},{"title":"Dolorous Mind (5 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, you choose one creature you can see within 60 feet of you. It must succeed on a Charisma saving throw, or it is incapacitated and has a speed of 0 until your concentration ends. It can repeat this saving throw at the end of each of its turns, ending the effect on itself on a success.\u003c/p\u003e"}]},{"group":"Avatar","title":"Crown of Disgust","introduction":"\u003cp\u003e\u003cem\u003eAvatar Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou cause a creature to be flooded with emotions of disgust.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, the area in a 5-foot radius around you is difficult terrain for any enemy that isn\u0027t immune to being frightened.\u003c/p\u003e","abilities":[{"title":"Eye of Horror (1-7 psi).","content":"\u003cp\u003eAs an action, choose one creature you can see within 60 feet of you. The target must make a Charisma saving throw. On a failed save, it takes 1d6 psychic damage per psi point spent and can\u0027t move closer to you until the end of its next turn. On a successful save, it takes half as much damage.\u003c/p\u003e"},{"title":"Wall of Repulsion (3 psi; conc., 10 min.).","content":"\u003cp\u003eAs an action, you create an invisible, insubstantial wall of energy within 60 feet of you that is up to 30 feet long, 10 feet high, and 1 foot thick. The wall lasts until your concentration ends. Any creature attempting to move through it must make a Wisdom saving throw. On a failed save, a creature can\u0027t move through the wall until the start of its next turn. On a successful save, the creature can pass through the wall and is not affected by its presence.\u003c/p\u003e"},{"title":"Visions of Disgust (5 psi; conc., 1 min.).","content":"\u003cp\u003eYou cause a creature to regard all other beings as horrid, alien entities. As an action, choose one creature you can see within 60 feet of you. The target must make a Wisdom saving throw. On a failed save, it takes 5d6 psychic damage, and until your concentration ends, it takes 1d6 psychic damage per creature within 5 feet of it at the end of each of its turns. On a successful save, the target takes only half the initial damage and suffers none of the other effects.\u003c/p\u003e"},{"title":"World of Horror (7 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, choose up to six creatures within 60 feet of you. Each target must make a Charisma saving throw. On a failed save, a target takes 8d6 psychic damage, and it is frightened until your concentration ends. On a successful save, a target takes half as much damage.\u003c/p\u003e\r\n          \u003cp\u003eWhile frightened by this effect, a target\u0027s speed is reduced to 0, and the target can use its action and any bonus action it might have only to make melee attacks. The frightened target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.\u003c/p\u003e"}]},{"group":"Avatar","title":"Crown of Rage","introduction":"\u003cp\u003e\u003cem\u003eAvatar Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou place a mote of pure fury within a creature\u0027s mind, causing its bloodlust to overcome its senses and for it to act as you wish it to.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While you are focused on this discipline, any enemy within 5 feet of you that makes a melee attack roll against creatures other than you does so with disadvantage.\u003c/p\u003e","abilities":[{"title":"Primial Fury (1-7 psi).","content":"\u003cp\u003eAs an action, choose one creature you can see within 60 feet of you. The target must succeed on a Charisma saving throw or take 1d6 psychic damage per psi point spent on this ability and immediately use its reaction to move its speed in a straight line toward its nearest enemy. The save automatically succeeds if the target is immune to being charmed.\u003c/p\u003e"},{"title":"Fighting Words (2 psi; conc., 10 min.).","content":"\u003cp\u003eIf you spend 1 minute conversing with a creature, you can attempt to leave a simmering violence in its mind. At the end of the minute, you can use an action to force the creature to make a Wisdom saving throw to resist feeling violent urges against one creature you describe to it or name. The save automatically succeeds if the target is immune to being charmed. On a failed save, the target attacks the chosen creature if it sees that creature before your concentration ends, using weapons or spells against a creature it was hostile toward or unnamed strikes against any ally or a creature it was neutral toward. Once the fight starts, it continues to attack for 5 rounds before this effect ends. This effect immediately ends if the target or any ally it can see is attacked or takes damage from any creature other than the one it has been incited against. On a successful save, the creature is unaffected and has no inkling of your attempt to bend its will.\u003c/p\u003e"},{"title":"Mindless Courage (2 psi).","content":"\u003cp\u003eYou cause a creature\u0027s bloodlust to overcome its sense of preservation. As a bonus action, choose one creature you can see within 60 feet of you. The target must succeed on a Wisdom saving throw or, until the end of your next turn, it can\u0027t willingly move unless its movement brings it closer to the nearest enemy that it can see. The save automatically succeeds if the target is immune to being charmed.\u003c/p\u003e"},{"title":"Punishing Fury (5 psi; conc., 1 min.).","content":"\u003cp\u003eAs a bonus action, choose up to three creatures you can see within 60 feet of you. Each target can immediately use its reaction to move up to its speed in a straight line toward the nearest enemy. The save automatically succeeds if the target is immune to being charmed.\u003c/p\u003e"}]},{"group":"Avatar","title":"Mantle of Command","introduction":"\u003cp\u003e\u003cem\u003eAvatar Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou exert an aura of trust and authority, enhancing the coordination among your allies.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, when you end your turn and didn\u0027t move during it, you can use your reaction to allow one ally you can see within 30 feet of you to move up to half their speed, following a path of your choice. To move in this way, the ally must be incapacitated.\u003c/p\u003e","abilities":[{"title":"Coordinated Movement (2 psi).","content":"\u003cp\u003eAs a bonus action, choose up to five allies you can see within 60 feet of you. Each of those allies can use their reaction to move up to half their speed, following a path of your choice.\u003c/p\u003e"},{"title":"Commander\u0027s Sight (2 psi; conc., 1 round).","content":"\u003cp\u003eAs an action, choose one creature you can see within 60 feet of you. Until the start of your next turn, your allies have advantage on attack rolls against that target.\u003c/p\u003e"},{"title":"Command to Strike (3 psi).","content":"\u003cp\u003eAs an action, choose one ally you can see within 60 feet of you. That ally can use their reaction to immediately take the Attack action. You choose the targets.\u003c/p\u003e"},{"title":"Strategic Mind (5 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, you exert an aura of trust and command that unites your allies into a cohesive unit. Until your concentration ends, any ally within 60 feet of you on their turn can, as a bonus action, take the Dash or Disengage action or roll a d4 and add the number rolled to the damage roll of each attack they make that turn.\u003c/p\u003e"},{"title":"Overwhelming Attack (7 psi).","content":"\u003cp\u003eAs an action, choose up to five allies you can see within 60 feet of you. Each of those allies can use their reaction to take the Attack action. You choose the targets of the attacks.\u003c/p\u003e"}]},{"group":"Avatar","title":"Mantle of Courage","introduction":"\u003cp\u003e\u003cem\u003eAvatar Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou focus your mind on courage, radiating confidence and bravado to your allies.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you and allies within 10 feet of you who can see you have advantage on saving throws against being frightened.\u003c/p\u003e","abilities":[{"title":"Incite Courage (2 psi).","content":"\u003cp\u003eAs a bonus action, choose up to six creatures you can see within 60 feet of you. If any of those creatures is frightened, that condition ends on that creature.\u003c/p\u003e"},{"title":"Aura of Victory (1-7 psi; conc., 10 min.).","content":"\u003cp\u003eAs a bonus action, you project psionic energy until your concentration ends. The energy fortifies you and your allies when your enemies are felled; whenever an enemy you can see is reduced to 0 hit points, you and each of your allies within 30 feet of you gain temporary hit points equal to double the psi points spent to activate this effect.\u003c/p\u003e"},{"title":"Pillar of Confidence (6 psi; conc., 1 round).","content":"\u003cp\u003eAs an action, you and up to five creatures you can see within 60 feet of you each gain one extra action to use on your individual turns. The action goes away if it is used before the end of your next turn, or the action can be used only to make one weapon attack or to take the Dash or Disengage action.\u003c/p\u003e"}]},{"group":"Avatar","title":"Mantle of Fear","introduction":"\u003cp\u003e\u003cem\u003eAvatar Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou tap into a well of primal fear and turn yourself into a beacon of terror to your enemies.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you have advantage on Charisma (Intimidation) checks.\u003c/p\u003e","abilities":[{"title":"Incite Fear (2 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, choose one creature you can see within 60 feet of you. The target must succeed on a Wisdom saving throw or become frightened of you until your concentration ends. Whenever the frightened target ends its turn in a location where it can\u0027t see you, it can repeat the saving throw, ending the effect on itself on a success.\u003c/p\u003e"},{"title":"Unsettling Aura (3 psi; conc., 1 hr.).","content":"\u003cp\u003eAs a bonus action, you cloak yourself in unsettling psychic energy. Until your concentration ends, any enemy within 60 feet of you that can see you must spend 1 extra foot of movement for every foot it moves toward you. A creature ignores this effect if it is immune to being frightened.\u003c/p\u003e"},{"title":"Incite Panic (5 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, choose up to eight creatures you can see within 90 feet of you that can see you. At the start of each of a target\u0027s turns before your concentration ends, the target must make a Wisdom saving throw. On a failed save, the target is frightened until the start of its next turn, and you roll a d8. If you roll an odd number, the frightened target moves half its speed in a random direction and takes no action on that turn; other than to scream in terror. If you roll an even number, the frightened target makes one melee attack against a random target within its reach. If there is no such target, it moves half its speed in a random direction and takes no action on that turn. This effect ends on a target if it succeeds on three saving throws against it.\u003c/p\u003e"}]},{"group":"Avatar","title":"Mantle of Fury","introduction":"\u003cp\u003e\u003cem\u003eAvatar Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou allow the primal fury lurking deep within your mind to burst forth, catching you and your allies in an implausible bloodthirst.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline in combat, you and any ally who starts their turn within 10 feet of you gains a 5-foot increase to their walking speed during that turn.\u003c/p\u003e","abilities":[{"title":"Incite Fury (2 psi; conc., 1 min.).","content":"\u003cp\u003eAs a bonus action, choose up to three allies you can see within 60 feet of you. Each target can immediately use its reaction to move up to its speed in a straight line toward the nearest enemy.\u003c/p\u003e"},{"title":"Aura of Bloodletting (3 psi; conc., 1 min.).","content":"\u003cp\u003eAs a bonus action, you unleash an aura of rage. Until your concentration ends, you and any creature within 60 feet of you that has advantage on melee attack rolls.\u003c/p\u003e"},{"title":"Overwhelming Fury (5 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, you flood rage into one creature you can see within 60 feet of you. The target must succeed on a Charisma saving throw, or it can use its actions only to make melee attacks until your concentration ends. It can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.\u003c/p\u003e"}]},{"group":"Avatar","title":"Mantle of Joy","introduction":"\u003cp\u003e\u003cem\u003eAvatar Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou tap into the joy within you, radiating it outward in soothing, psychic energy that brings hope and comfort to creatures around you.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you have advantage on Charisma (Persuasion) checks.\u003c/p\u003e","abilities":[{"title":"Sooting Presence (1-7 psi).","content":"\u003cp\u003eAs a bonus action, choose up to three creatures you can see within 60 feet of you. Each target gains 3 temporary hit points per psi point spent on this effect.\u003c/p\u003e"},{"title":"Comforting Aura (2 psi; conc., 1 min.).","content":"\u003cp\u003eAs a bonus action, choose up to three allies you can see (you can choose yourself in place of one of the allies). Until your concentration ends, each target can roll a d4 when making a saving throw and add the number rolled to the total.\u003c/p\u003e"},{"title":"Aura of Jubilation (3 psi; conc., 1 min.).","content":"\u003cp\u003eAs a bonus action, you radiate a distracting mirth until your concentration ends. Each creature within 60 feet of you that can see you suffers disadvantage on any checks using the Perception and Investigation skills.\u003c/p\u003e"},{"title":"Beacon of Recovery (5 psi).","content":"\u003cp\u003eAs a bonus action, you and up to five allies you can see within 60 feet of you can immediately make saving throws against every effect they\u0027re suffering that allows a save at the start or end of their turns.\u003c/p\u003e"}]},{"group":"Awakened","title":"Aura Sight","introduction":"\u003cp\u003e\u003cem\u003eAwakened Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou refocus your sight to see the energy that surrounds all creatures. You perceive auras, energy signatures that can reveal key elements of a creature\u0027s nature.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you have advantage on Wisdom (Insight) checks.\u003c/p\u003e","abilities":[{"title":"Assess Foe (2 psi).","content":"\u003cp\u003eAs a bonus action, you analyze the aura of one creature you see. You learn its current hit point total and all its immunities, resistances, and vulnerabilities.\u003c/p\u003e"},{"title":"Read Moods (2 psi).","content":"\u003cp\u003eAs a bonus action, you learn a one-word summary of the emotional state of up to six creatures you can see, such as happy, confused, afraid, or violent.\u003c/p\u003e"},{"title":"View Aura (3 psi; conc., 1 hr.).","content":"\u003cp\u003eAs an action, you study one creature\u0027s aura. Until your concentration ends, while you can see the target, you learn if it\u0027s under the effect of any magical or psionic effects, its current hit point total, and its basic emotional state. While this effect lasts, you have advantage on Wisdom (Insight) and Charisma checks you make against it.\u003c/p\u003e"},{"title":"Perceive the Unseen (5 psi; conc., 1 min.).","content":"\u003cp\u003eAs a bonus action, you gain the ability to see auras even of invisible or hidden creatures. Until your concentration ends, you can see all creatures, including hidden and invisible ones, regardless of lighting conditions.\u003c/p\u003e"}]},{"group":"Awakened","title":"Intellect Fortress","introduction":"\u003cp\u003e\u003cem\u003eAwakened Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou forge an indomitable wall of psionic energy around your mind - one that allows you to launch counterattacks against your opponents.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you gain resistance to psychic damage.\u003c/p\u003e","abilities":[{"title":"Psychic Backlash (2 psi).","content":"\u003cp\u003eAs a reaction, you can impose disadvantage on an attack roll against you if you can see the attacker. If the attack still hits you, the attacker takes 2d10 psychic damage.\u003c/p\u003e"},{"title":"Psychic Parry (1-7 psi).","content":"\u003cp\u003eAs a reaction when you make an Intelligence, a Wisdom, or a Charisma saving throw, you gain a +1 bonus to that saving throw for each psi point you spend on this ability. You can use this ability after rolling the die but before suffering the results.\u003c/p\u003e"},{"title":"Psychic Rebound (5 psi; conc., 10 min.).","content":"\u003cp\u003eAs an action, you create a field of protective psychic energy. Choose any number of creatures within 30 feet of you. Until your concentration ends, each target has resistance to psychic damage and advantage on Intelligence, Wisdom, and Charisma saving throws.\u003c/p\u003e"}]},{"group":"Awakened","title":"Mantle of Awe","introduction":"\u003cp\u003e\u003cem\u003eAwakened Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou learn to use psionic energy to manipulate others with a subtle combination of psi and your own, natural charm.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you gain a bonus to Charisma checks. The bonus equals half your Intelligence modifier (minimum of +1).\u003c/p\u003e","abilities":[{"title":"Charming Presence (1-7 psi).","content":"\u003cp\u003eAs an action, you exert an aura of sympathetic power. Roll 2d8 per psi point spent on this ability; the total is how many hit points worth of creatures this option can affect. Creatures within 30 feet of you are affected in ascending order of their hit point maximums, ignoring incapacitated creatures, creatures immune to being charmed, and creatures engaged in combat. Starting with the creature that has the lowest hit point maximum, each creature affected by this option is charmed by you for 10 minutes, regarding you as a friendly acquaintance. Subtract each creature\u0027s hit point maximum from the total before moving on to the next creature. A creature\u0027s hit point maximum must be equal to or less than the remaining total for that creature to be affected.\u003c/p\u003e"},{"title":"Center of Attention (2 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, you exert an aura of power that grabs a creature\u0027s attention. Choose one creature you can see within 60 feet of you. It must make a Charisma saving throw. On a failed save, the creature is so thoroughly distracted by you that all other creatures are invisible to it until your concentration ends. This effect ends if the creature can no longer see or hear you or if it takes damage.\u003c/p\u003e"},{"title":"Invoke Awe (7 psi; conc., 10 min.).","content":"\u003cp\u003eAs an action, you exert an aura that inspires awe in others. Choose up to 5 creatures you can see within 60 feet of you. Each target must succeed on an Intelligence saving throw or be charmed by you until your concentration ends. While charmed, the target obeys all your verbal commands to the best of its ability and without doing anything obviously self-destructive. The charmed target will attack only creatures that it has seen attack you since it was charmed or that it has already hostile toward. At the end of each of its turns, it can repeat the saving throw, ending the effect on itself on a success.\u003c/p\u003e"}]},{"group":"Awakened","title":"Psychic Assault","introduction":"\u003cp\u003e\u003cem\u003eAwakened Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou wield your mind like a weapon, unleashing salvos of psionic energy.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you gain a +2 bonus to damage rolls with psionic talents that deal psychic damage.\u003c/p\u003e","abilities":[{"title":"Psionic Blast (1-7 psi).","content":"\u003cp\u003eAs an action, choose one creature you can see within 60 feet of you. The target takes 1d8 psychic damage per psi point spent on this ability.\u003c/p\u003e"},{"title":"Ego Whip (3 psi).","content":"\u003cp\u003eAs an action, choose one creature you can see within 60 feet of you. The target must make an Intelligence saving throw. On a failed save, the creature takes 3d8 psychic damage, and it is filled with self-doubt, leaving it able to use its action on its next turn only to take the Dodge, Disengage, or Hide action. On a successful save, it takes half as much damage.\u003c/p\u003e"},{"title":"Id Insinuation (5 psi).","content":"\u003cp\u003eAs an action, choose one creature you can see within 60 feet of you. The target must make an Intelligence saving throw. On a failed save, the creature takes 5d8 psychic damage, and it goes into a fury, as its id runs rampant. On its next turn, it can use its action only to take the Dodge or Attack action. On a successful save, it takes half as much damage.\u003c/p\u003e"},{"title":"Psychic Blast (6 psi).","content":"\u003cp\u003eAs an action, you unleash devastating psychic energy in a 60-foot cone. Each creature in that area must make an Intelligence saving throw, taking 8d8 psychic damage on a failed save, or half as much damage on a successful one. You can increase the damage by 2d8 if you spend 1 more psi point on this ability.\u003c/p\u003e"},{"title":"Psychic Crush (7 psi).","content":"\u003cp\u003eAs an action, you create a 20-foot cube of psychic energy within 120 feet of you. Each creature in that area must make an Intelligence saving throw. On a failed save, a target takes 8d8 psychic damage and is stunned until the end of your next turn. On a successful save, a target takes half as much damage.\u003c/p\u003e"}]},{"group":"Awakened","title":"Psychic Disruption","introduction":"\u003cp\u003e\u003cem\u003eAwakened Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou create psychic static that disrupts other creatures\u0027 ability to think clearly.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you have advantage on Charisma (Deception) checks.\u003c/p\u003e","abilities":[{"title":"Distracting Haze (1-7 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, choose one creature you can see within 60 feet of you. That creature must make an Intelligence saving throw. On a failed save, it takes 1d10 psychic damage per psi point spent and can\u0027t see anything more than 10 feet from it until your concentration ends. On a successful save, it takes half as much damage.\u003c/p\u003e"},{"title":"Daze (3 psi).","content":"\u003cp\u003eAs an action, choose one creature you can see within 60 feet of you. That creature must make an Intelligence saving throw. On a failed save, the target is incapacitated until the end of your next turn or until it takes any damage.\u003c/p\u003e"},{"title":"Mind Storm (5 psi).","content":"\u003cp\u003eAs an action, choose a point you can see within 60 feet of you. Each creature in a 20-foot-radius sphere centered on that point must make a Wisdom saving throw. On a failed save, a target takes 6d8 psychic damage and suffers disadvantage on all saving throws until the end of your next turn. On a successful save, a creature takes half as much damage. You can increase the damage by 1d6 per additional psi point spent on this ability.\u003c/p\u003e"}]},{"group":"Awakened","title":"Psychic Inquisition","introduction":"\u003cp\u003e\u003cem\u003eAwakened Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou reach into a creature\u0027s mind to uncover information or plant ideas within it.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you know when a creature communicating with you via telepathy is lying.\u003c/p\u003e","abilities":[{"title":"Hammer of Inquisition (1-7 psi).","content":"\u003cp\u003eAs an action, choose one creature you can see within 60 feet of you. The target must make an Intelligence saving throw. On a failed save, it takes 1d10 psychic damage per psi point spent and suffers disadvantage on its next Wisdom saving throw before the end of your next turn. On a successful save, it takes half as much damage.\u003c/p\u003e"},{"title":"Forceful Query (2 psi).","content":"\u003cp\u003eAs an action, you ask a question of one creature that can see and hear you within 30 feet of you. The question must be phrased so that it can be answered with a yes or no, otherwise this ability fails. The target must succeed on a Wisdom saving throw, or it replies with a truthful answer. A creature is immune to this ability if it is immune to being charmed.\u003c/p\u003e"},{"title":"Ransack Mind (5 psi; conc., 1 hr.).","content":"\u003cp\u003eWhile you concentrate on this ability, you probe one creature\u0027s mind. The creature must remain within 30 feet of you, and you must be able to see it. If you reach the ability\u0027s full duration, the target must make three Intelligence saving throws, and you gain information from it based on the number of saving throws it fails:\u003c/p\u003e\r\n          \u003cul\u003e\r\n            \u003cli\u003eWith one failed saving throw, you learn its memories from the past 12 hours.\u003c/li\u003e\r\n            \u003cli\u003eWith two failed saving throws, you learn its memories from the past 24 hours.\u003c/li\u003e\r\n            \u003cli\u003eWith three failed saving throws, you learn its memories from the past 48 hours.\u003c/li\u003e\r\n          \u003c/ul\u003e"},{"title":"Phantom Idea (6 psi; conc., 1 hr.).","content":"\u003cp\u003eWhile you concentrate on this ability, you probe one creature\u0027s mind. The creature must remain within 30 feet of you, and you must be able to see it. If you reach the ability\u0027s full duration, the target must make three Intelligence saving throws, and you plant a memory or an idea in it, which lasts for a number of hours based on the number of saving throws it fails. You choose whether the idea or memory is trivial (such as \"I had porridge for breakfast\" or \"Ale is the worst\") or personally-defining (\"I failed to save my village from orc marauders and am therefore a coward\") or \"Magic is a scourge, so I renounce it\").\u003c/p\u003e\r\n          \u003cul\u003e\r\n            \u003cli\u003eWith one failed saving throw, the idea or memory lasts for the next 4 hours.\u003c/li\u003e\r\n            \u003cli\u003eWith two failed saving throws, it lasts for 24 hours.\u003c/li\u003e\r\n            \u003cli\u003eWith three failed saving throws, it lasts for 48 hours.\u003c/li\u003e\r\n          \u003c/ul\u003e"}]},{"group":"Awakened","title":"Recognition","introduction":"\u003cp\u003e\u003cem\u003eAwakened Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eBy analyzing information around you, from subtle hints to seemingly disconnected facts, you learn to weave a string of probabilities in an instant that gives you extraordinary insights.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you have advantage on initiative rolls.\u003c/p\u003e","abilities":[{"title":"Precognitive Hunch (2 psi; conc., 1 min.).","content":"\u003cp\u003eAs a bonus action, you open yourself to receive momentary insights that improve your odds of success; until your concentration ends, whenever you make an attack roll, a saving throw, or an ability check, you roll a d4 and add it to the total.\u003c/p\u003e"},{"title":"All-Around Gift (3 psi).","content":"\u003cp\u003eIn response to an attack hitting you, you use your reaction to impose disadvantage on that attack roll, possibly causing it to miss.\u003c/p\u003e"},{"title":"Danger Sense (5 psi; conc., 8 hr.).","content":"\u003cp\u003eAs an action, you create a psychic model of reality in your mind and set it to show you a few seconds into the future. Until your concentration ends, you can\u0027t be surprised, attack rolls against you can\u0027t gain advantage, and you gain a +10 bonus to initiative.\u003c/p\u003e"},{"title":"Victory Before Battle (7 psi).","content":"\u003cp\u003eWhen you roll initiative, you can use this ability to grant yourself and up to five creatures of your choice within 60 feet of you a +10 bonus to initiative.\u003c/p\u003e"}]},{"group":"Awakened","title":"Telepathic Contact","introduction":"\u003cp\u003e\u003cem\u003eAwakened Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eBy channeling psionic power, you gain the ability to control other creatures by substituting your will for their own.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you gain the ability to use your Telepathy class feature with up to six creatures at once. If you don\u0027t have that feature from the mystic class, you instead gain it while focused on this discipline.\u003c/p\u003e","abilities":[{"title":"Exacting Query (2 psi).","content":"\u003cp\u003eAs an action, you target one creature you can communicate with via telepathy. The target must make an Intelligence saving throw. On a failed save, the target truthfully answers one question you ask it via telepathy. On a successful save, the target is unaffected, and you can\u0027t use this ability on it again until you finish a long rest. A creature is immune to this ability if it is immune to being charmed.\u003c/p\u003e"},{"title":"Occluded Mind (2 psi).","content":"\u003cp\u003eAs an action, you target one creature you can communicate with via telepathy. The target must make an Intelligence saving throw. On a failed save, the target believes one statement of your choice for the next 5 minutes that you communicate to it via telepathy. The statement can be up to ten words long, and it must describe you or a creature of an object the target can see. On a successful save, the target is unaffected, and you can\u0027t use this ability on it again until you finish a long rest. A creature is immune to this ability if it is immune to being charmed.\u003c/p\u003e"},{"title":"Broken Will (5 psi).","content":"\u003cp\u003eAs an action, you target one creature you can communicate with via telepathy. The target must make an Intelligence saving throw. On a failed save, you choose the target\u0027s movement and action on its next turn. On a successful save, the target is unaffected, and you can\u0027t use this ability on it again until you finish a long rest. A creature is immune to this ability if it is immune to being charmed.\u003c/p\u003e"},{"title":"Psychic Grip (6 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, you target one creature you can see within 60 feet of you. The target must succeed on an Intelligence saving throw, or it is paralyzed until your concentration ends. At the end of each of its turns, it can repeat the saving throw. On a success, this effect ends. On a failure, you can use your reaction to force the target to move up to half its speed, even though it\u0027s paralyzed.\u003c/p\u003e"},{"title":"Psychic Domination (7 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, you target one creature you can see within 60 feet of you. The target must succeed on an Intelligence saving throw, or you choose the creature\u0027s actions and movement on its turns until your concentration ends. At the end of each of its turns, it can repeat the saving throw, ending the effect on itself on a success. A creature is immune to this ability if it is immune to being charmed.\u003c/p\u003e"}]},{"group":"Immortal","title":"Adaptive Body","introduction":"\u003cp\u003e\u003cem\u003eImmortal Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou can alter your body to match your surroundings, allowing you to withstand punishing environments. With greater psi energy, you can extend this protection to others.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you don\u0027t need to eat, breathe, or sleep. To gain the benefits of a long rest, you can spend 8 hours engaged in light activity, rather than sleeping during any of it.\u003c/p\u003e","abilities":[{"title":"Environmental Adaptation (2 psi).","content":"\u003cp\u003eAs an action, you or a creature you touch ignores the effects of extreme heat or cold (but not cold or fire damage) for the next hour.\u003c/p\u003e"},{"title":"Adaptive Shield (3 psi).","content":"\u003cp\u003eWhen you take acid, cold, fire, lightning, or thunder damage, you can use your reaction to gain resistance to that damage of the type-including the triggering damage-until the end of your next turn.\u003c/p\u003e"},{"title":"Energy Adaptation (5 psi; conc., 1 hr.).","content":"\u003cp\u003eAs an action, you can touch one creature and give it resistance to acid, cold, fire, lightning, or thunder damage (your choice), which lasts until your concentration ends.\u003c/p\u003e"},{"title":"Energy Immunity (7 psi; conc., 1 hr.).","content":"\u003cp\u003eAs an action, you can touch one creature and give it immunity to acid, cold, fire, lightning, or thunder damage (your choice), which lasts until your concentration ends.\u003c/p\u003e"}]},{"group":"Immortal","title":"Bestial Form","introduction":"\u003cp\u003e\u003cem\u003eImmortal Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou transform your body, gaining traits of different beasts.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you have advantage on Wisdom (Animal Handling) checks.\u003c/p\u003e","abilities":[{"title":"Bestial Claws (1-7 psi).","content":"\u003cp\u003eYou manifest long claws for an instant and make a melee weapon attack against one creature within 5 feet of you. On a hit, this attack deals 1d10 slashing damage per psi point spent.\u003c/p\u003e"},{"title":"Bestial Transformation.","content":"\u003cp\u003eAs a bonus action, you alter your physical form to gain different characteristics. When you use this ability, you can choose one or more of the following effects. Each effect has its own psi point cost. Add them together to determine the total cost. This transformation lasts for 1 hour, until you die, or until you end it as a bonus action.\u003c/p\u003e\r\n          \u003cul\u003e\r\n            \u003cli\u003e\u003cstrong\u003eAmphibious\u003c/strong\u003e (2 psi). You gain gills; you can breathe air and water.\u003c/li\u003e\r\n            \u003cli\u003e\u003cstrong\u003eClimbing\u003c/strong\u003e (2 psi). You grow tiny hooked claws that give you a climbing speed equal to your walking speed.\u003c/li\u003e\r\n            \u003cli\u003e\u003cstrong\u003eFlight\u003c/strong\u003e (5 psi). Wings sprout from your back. You gain a flying speed equal to your walking speed.\u003c/li\u003e\r\n            \u003cli\u003e\u003cstrong\u003e Keen Senses\u003c/strong\u003e (2 psi). Your eyes and ears become more sensitive. You gain advantage on Wisdom (Perception) checks.\u003c/li\u003e\r\n            \u003cli\u003e\u003cstrong\u003ePerfect Senses\u003c/strong\u003e (3 psi). You gain a keen sense of smell and an instinct to detect prey. You can see invisible creatures and objects within 10 feet of you, even if you are blinded.\u003c/li\u003e\r\n            \u003cli\u003e\u003cstrong\u003eSwimming\u003c/strong\u003e (2 psi). You gain fins and webbing between your fingers and toes; you gain a swimming speed equal to your walking speed.\u003c/li\u003e\r\n            \u003cli\u003e\u003cstrong\u003eTough Hide\u003c/strong\u003e (2 psi). Your skin becomes as tough as leather; you gain a +2 bonus to AC.\u003c/li\u003e\r\n          \u003c/ul\u003e"}]},{"group":"Immortal","title":"Brute Force","introduction":"\u003cp\u003e\u003cem\u003eImmortal Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou augment your natural strength with psionic energy, granting you the ability to achieve incredible feats of might.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you have advantage on Strength (Athletics) checks.\u003c/p\u003e","abilities":[{"title":"Brute Strike (1-7 psi).","content":"\u003cp\u003eAs a bonus action, you gain a bonus to your next damage roll against a target you hit with a melee attack during the current turn. The bonus equals +1d6 per psi point spent, and the bonus damage is the same type as the attack. If the attack has more than one damage type, you choose which one to use for the bonus damage.\u003c/p\u003e"},{"title":"Knock Back (1-7 psi).","content":"\u003cp\u003eWhen you hit a target with a melee attack, you can activate this ability as a reaction. The target must succeed on a Strength saving throw or be knocked 10 feet away from you per psi point spent. The target moves in a straight line. If it hits an object, this movement immediately ends and the target takes 1d6 bludgeoning damage per psi point spent.\u003c/p\u003e"},{"title":"Mighty Leap (1-7 psi).","content":"\u003cp\u003eAs part of your movement, you jump in any direction up to 20 feet per psi point spent.\u003c/p\u003e"},{"title":"Feat of Strength (2 psi).","content":"\u003cp\u003eAs a bonus action, you gain a +5 bonus to Strength checks until the end of your next turn.\u003c/p\u003e"}]},{"group":"Immortal","title":"Celerity","introduction":"\u003cp\u003e\u003cem\u003eImmortal Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou channel psionic power into your body, honing your reflexes and agility to an incredible degree. The world seems to slow down while you continue to move as normal.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, your walking speed increases by 10 feet.\u003c/p\u003e","abilities":[{"title":"Rapid Step (1-7 psi).","content":"\u003cp\u003eAs a bonus action, you increase your walking speed by 10 feet per psi point spent until the end of the current turn. If you have a climbing or swimming speed, this increase applies to that speed as well.\u003c/p\u003e"},{"title":"Agile Defense (2 psi).","content":"\u003cp\u003eAs a bonus action, you take the Dodge action.\u003c/p\u003e"},{"title":"Blur of Motion (2 psi).","content":"\u003cp\u003eAs an action, you cause yourself to be invisible during any of your movement during the current turn.\u003c/p\u003e"},{"title":"Surge of Speed (2 psi).","content":"\u003cp\u003eAs a bonus action, you gain two benefits until the end of the current turn: you don\u0027t provoke opportunity attacks, and you have a climbing speed equal to your walking speed.\u003c/p\u003e"},{"title":"Surge of Action (5 psi).","content":"\u003cp\u003eAs a bonus action, you can Dash or make one weapon attack.\u003c/p\u003e"}]},{"group":"Immortal","title":"Corrosive Metabolism","introduction":"\u003cp\u003e\u003cem\u003eImmortal Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYour control over your body allows you to deliver acid or poison attacks.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you have resistance to acid and poison damage.\u003c/p\u003e","abilities":[{"title":"Corrosive Touch (1-7 psi).","content":"\u003cp\u003eAs an action, you deliver a touch of acid to a creature within your reach. The target must make a Dexterity saving throw, taking 1d10 acid damage per psi point spent on a failed save, or half as much on a successful one.\u003c/p\u003e"},{"title":"Venom Strike (1-7 psi).","content":"\u003cp\u003eAs an action, you create a poison spray that targets one creature you can see within 30 feet of you. The target must make a Constitution saving throw. On a failed save, it takes 1d6 poison damage per psi point spent and is poisoned until the end of your next turn. On a successful save, it takes half as much damage.\u003c/p\u003e"},{"title":"Acid Spray (2 psi).","content":"\u003cp\u003eAs a reaction when you take piercing or slashing damage, you cause acid to spray from your wound; each creature within 5 feet of you takes 2d6 acid damage.\u003c/p\u003e"},{"title":"Breath of the Black Dragon (5 psi).","content":"\u003cp\u003eYou exhale a wave of acid in a 60-foot line that is 5 feet wide. Each creature in the line must make a Constitution saving throw, taking 6d6 acid damage on a failed save, or half as much on a successful one. You can increase the damage by 1d6 per additional psi point spent on it.\u003c/p\u003e"},{"title":"Breath of the Green Dragon (7 psi).","content":"\u003cp\u003eYou exhale a cloud of poison in a 90-foot cone. Each creature in the cone must make a Constitution saving throw, taking 10d6 poison damage on a failed save, or half as much damage on a successful one.\u003c/p\u003e"}]},{"group":"Immortal","title":"Diminution","introduction":"\u003cp\u003e\u003cem\u003eImmortal Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou manipulate the matter that composes your body, drastically reducing your size without surrendering any of your might.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you have advantage on Dexterity (Stealth) checks.\u003c/p\u003e","abilities":[{"title":"Miniature Form (2 psi; conc., 10 min.).","content":"\u003cp\u003eAs a bonus action, you become Tiny until your concentration ends. While this size, you gain a +5 bonus to Dexterity (Stealth) checks and can move through gaps up to 6 inches across without squeezing.\u003c/p\u003e"},{"title":"Toppling Shift (2 psi).","content":"\u003cp\u003eAs a bonus action, you shift to an incredibly small size and then suddenly return to normal, sending an opponent flying backward. Choose one creature you can see within 5 feet of you. It must succeed on a Strength saving throw or be knocked prone.\u003c/p\u003e"},{"title":"Sudden Shift (5 psi).","content":"\u003cp\u003eAs a reaction when you are hit by an attack, you shift down to minute size to avoid the attack. The attack misses, and you move up to 5 feet without provoking opportunity attacks before returning to normal size.\u003c/p\u003e"},{"title":"Microscopic Form (7 psi; conc., 10 min.).","content":"\u003cp\u003eAs a bonus action, you become smaller than Tiny until your concentration ends. While this size, you gain a +10 bonus to Dexterity (Stealth) checks and a +5 bonus to AC, you can move through gaps up to 1 inch across without squeezing, and you can\u0027t make weapon attacks.\u003c/p\u003e"}]},{"group":"Immortal","title":"Giant Growth","introduction":"\u003cp\u003e\u003cem\u003eImmortal Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou infuse yourself with psionic energy to grow to tremendous size, bolstering your strength and durability.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, your reach increases by 5 feet.\u003c/p\u003e","abilities":[{"title":"Ogre Form (2 psi; conc., 1 min.).","content":"\u003cp\u003eAs a bonus action, you gain 10 temporary hit points. In addition, until your concentration ends, your melee weapon attacks deal an extra 1d4 bludgeoning damage on a hit, and your reach increases by 5 feet. If you\u0027re smaller than Large, you also become Large for the duration.\u003c/p\u003e"},{"title":"Giant Form (7 psi; conc., 1 min.).","content":"\u003cp\u003eAs a bonus action, you gain 30 temporary hit points. In addition, until your concentration ends, your melee weapon attacks deal an extra 2d6 bludgeoning damage on a hit, and your reach increases by 10 feet. If you\u0027re smaller than Huge, you also become Huge for the duration.\u003c/p\u003e"}]},{"group":"Immortal","title":"Iron Durability","introduction":"\u003cp\u003e\u003cem\u003eImmortal Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou transform your body to become a living metal, allowing you to shrug off attacks that would cripple weaker creatures.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you gain a +1 bonus to AC.\u003c/p\u003e","abilities":[{"title":"Iron Hide (1-7 psi).","content":"\u003cp\u003eAs a reaction when you are hit by an attack, you gain a +1 bonus to AC for each psi point you spend on this ability. The bonus lasts until the end of your next turn. This bonus applies against the triggering attack.\u003c/p\u003e"},{"title":"Steel Hide (2 psi).","content":"\u003cp\u003eAs a bonus action, you gain resistance to bludgeoning, piercing, and slashing damage until the end of your next turn.\u003c/p\u003e"},{"title":"Iron Resistance (7 psi; conc., 1 hr.).","content":"\u003cp\u003eAs an action, you gain resistance to bludgeoning, piercing, or slashing damage (your choice), which lasts until your concentration ends.\u003c/p\u003e"}]},{"group":"Immortal","title":"Psionic Restoration","introduction":"\u003cp\u003e\u003cem\u003eImmortal Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou wield psionic energy to cure wounds and restore health to yourself and others.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you can use a bonus action to touch a creature that has 0 hit points and stabilize it.\u003c/p\u003e","abilities":[{"title":"Mend Wounds (1-7 psi).","content":"\u003cp\u003eAs an action, you can spend psi points to restore hit points to one creature you touch. The creature regains 1d8 hit points per psi point spent.\u003c/p\u003e"},{"title":"Restore Health (3 psi).","content":"\u003cp\u003eAs an action, you touch one creature and remove one of the following conditions from it: blinded, deafened, paralyzed, or poisoned. Alternatively, you remove one disease from the creature.\u003c/p\u003e"},{"title":"Restore Life (5 psi).","content":"\u003cp\u003eAs an action, you touch one creature that has died within the last minute. The creature returns to life with 1 hit point. This ability can\u0027t return a creature that had died of old age, nor can it restore a creature missing any vital body parts.\u003c/p\u003e"},{"title":"Restore Vigor (7 psi).","content":"\u003cp\u003eAs an action, you can touch one creature and choose one of the following: remove any reductions to one of its ability scores, remove one effect that reduces its hit point maximum, or reduce its exhaustion level by one.\u003c/p\u003e"}]},{"group":"Immortal","title":"Psionic Weapon","introduction":"\u003cp\u003e\u003cem\u003eImmortal Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou have learned how to channel psionic energy into your attacks, lending them devastating power.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e Whenever you focus on this discipline, choose one weapon you\u0027re holding or your unarmed strike. When you attack with it while focused on this discipline, its damage is psychic and magical, rather than its normal damage type. Until you reach 6th level, you don\u0027t add your Strength or Dexterity modifier to the psychic attack\u0027s damage rolls.\u003c/p\u003e","abilities":[{"title":"Ethereal Weapon (1 psi).","content":"\u003cp\u003eAs a bonus action, you temporarily transform one weapon you\u0027re holding or your unarmed strike into pure psionic energy. The next attack you make with it before the end of your turn ignores the target\u0027s armor, requiring no attack roll. Instead, the target makes a Dexterity saving throw against this discipline. On a failed save, the target takes the attack\u0027s normal damage and suffers its additional effects. On a successful save, the target takes half damage and suffers no additional effects. On a successful save, the target takes half damage from the attack but suffers no additional effects that would normally be imposed on a hit.\u003c/p\u003e"},{"title":"Lethal Strike (1-7 psi).","content":"\u003cp\u003eAs a bonus action, you imbue a weapon you\u0027re holding or your unarmed strike with psychic energy. The next time you hit it with it before the end of your turn, it deals an extra 1d10 psychic damage per psi point spent.\u003c/p\u003e"},{"title":"Augmented Weapon (5 psi; conc., 10 min.).","content":"\u003cp\u003eAs a bonus action, touch one simple or martial weapon. Until your concentration ends, that weapon becomes a magic weapon with a +3 bonus to its attack and damage rolls.\u003c/p\u003e"}]},{"group":"Nomad","title":"Nomadic Arrow","introduction":"\u003cp\u003e\u003cem\u003eNomad Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou imbue a ranged weapon with a strange semblance of sentience, allowing it to unerringly find its mark.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While you are focused on this discipline, any attack roll you make for a ranged weapon attack ignores disadvantage. If disadvantage would normally apply to the roll, that roll also can\u0027t benefit from advantage.\u003c/p\u003e","abilities":[{"title":"Speed Dart (1-7 psi).","content":"\u003cp\u003eAs a bonus action, you imbue one ranged weapon you hold with psionic power. The next attack you make with it that hits before the end of your current turn deals an extra 1d10 psychic damage per psi point spent.\u003c/p\u003e"},{"title":"Seeking Missile (2 psi).","content":"\u003cp\u003eAs a reaction when you miss with a ranged weapon attack, you can repeat the attack roll against the same target.\u003c/p\u003e"},{"title":"Faithful Archer (5 psi; conc., 1 min.).","content":"\u003cp\u003eAs a bonus action, you imbue a ranged weapon with a limited sentience. Until your concentration ends, you can make an extra attack with the weapon at the start of each of your turns (no action required). If it is a thrown weapon, it returns to your grasp each time you make any attack with it.\u003c/p\u003e"}]},{"group":"Nomad","title":"Nomadic Chameleon","introduction":"\u003cp\u003e\u003cem\u003eNomad Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou create a screen of psychic power that distorts your appearance, allowing you to blend into the background or even turn invisible.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you have advantage on Dexterity (Stealth) checks.\u003c/p\u003e","abilities":[{"title":"Chameleon (2 psi).","content":"\u003cp\u003eAs an action, you can attempt to hide even if you fail to meet the requirements needed to do so. At the end of the current turn, you remain hidden only if you then meet the normal requirements for hiding.\u003c/p\u003e"},{"title":"Step from Sight (3 psi; conc., 1 min.).","content":"\u003cp\u003eAs a bonus action, cloak yourself from sight. You can target one additional creature for every additional psi point you spend on this ability. The added targets must be visible to you and within 60 feet of you. Each target turns invisible and remains so until your concentration ends or until immediately after it targets, damages, or otherwise affects any creature with an attack, a spell, or another ability.\u003c/p\u003e"},{"title":"Enduring Invisibility (7 psi; conc., 1 min.).","content":"\u003cp\u003eAs a bonus action, you turn invisible and remain so until your concentration ends.\u003c/p\u003e"}]},{"group":"Nomad","title":"Nomadic Mind","introduction":"\u003cp\u003e\u003cem\u003eNomad Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou dispatch part of your psyche into the noosphere, the collective vista of minds and knowledge possessed by living things.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e Whenever you focus on this discipline, you choose one skill or tool and have proficiency with it until your focus ends. Alternatively, you gain the ability to read and write one language of your choice until your focus ends.\u003c/p\u003e","abilities":[{"title":"Wandering Mind (2-6 psi; conc., 10 min.).","content":"\u003cp\u003eYou enter a deep contemplation. If you concentrate for this option\u0027s full duration, you then gain proficiency with up to three of the following skills (one skill for every 2 psi points spent): Animal Handling, Arcana, History, Medicine, Nature, Performance, Religion, and Survival. The benefit lasts for 1 hour, no concentration required.\u003c/p\u003e"},{"title":"Find Creature (2 psi; conc., 1 hr.).","content":"\u003cp\u003eYou cast your mind about for information about a specific creature. If you concentrate for this option\u0027s full duration, you then gain a general understanding of the creature\u0027s current location. You learn the region, city, town, village, or district where it is, pinpointing an area between 1 and 3 miles on a side (DM\u0027s choice). If the creature is on another plane of existence, you instead learn which plane.\u003c/p\u003e"},{"title":"Item Lore (3 psi; conc., 1 hr.).","content":"\u003cp\u003eYou carefully study an item. If you concentrate for this option\u0027s full duration while remaining within 5 feet of the item, you then gain the benefits of an identify spell cast on that item.\u003c/p\u003e"},{"title":"Psychic Speech (5 psi).","content":"\u003cp\u003eAs an action, you attune your mind to the psychic imprint of all language. For 1 hour, you gain the ability to understand any language you hear or attempt to read. In addition, when you speak, all creatures that can understand a language understand what you say, regardless of what language you use.\u003c/p\u003e"},{"title":"Wandering Eye (6 psi; conc., 1 hr.).","content":"\u003cp\u003eAs an action, you create a psychic sensor within 60 feet of you. The sensor lasts until your concentration ends. The sensor can hover in the air. You mentally receive visual information from it, which has normal vision and darkvision with a range of 60 feet. The sensor can look in all directions. As an action, you can move the sensor up to 30 feet in any direction. There is no limit to how far away from you the eye can move, but it can\u0027t enter another plane of existence. A solid barrier blocks the eye\u0027s movement, but the eye can pass through an opening as small as 1 inch in diameter.\u003c/p\u003e"},{"title":"Phasing Eye (7 psi; conc., 1 hr.).","content":"\u003cp\u003eAs Wandering Eye above, except the eye can move through solid objects but can\u0027t end its movement in one. If it does so, the effect immediately ends.\u003c/p\u003e"}]},{"group":"Nomad","title":"Nomadic Step","introduction":"\u003cp\u003e\u003cem\u003eNomad Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou exert your mind on the area around you, twisting the intraplanar pathways you perceive to allow instantaneous travel.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e After you teleport on your turn while focused on this discipline, your walking speed increases by 10 feet until the end of the turn, as you are propelled by the magic of your teleportation. You can receive this increase only once per turn.\u003c/p\u003e","abilities":[{"title":"Step of a Dozen Paces (1-7 psi).","content":"\u003cp\u003eIf you haven\u0027t moved yet on your turn, you take a bonus action to teleport up to 20 feet per psi point spent to an unoccupied space you can see, and your speed is reduced to 0 until the end of the turn.\u003c/p\u003e"},{"title":"Nomadic Anchor (1 psi).","content":"\u003cp\u003eAs an action, you create an invisible, intangible teleportation anchor in a 5-foot cube you can see within 120 feet of you. For the next 8 hours, whenever you use this psionic discipline to teleport, you can instead teleport to the anchor, even if you can\u0027t see it, but it must be within range of the teleportation ability.\u003c/p\u003e"},{"title":"Defensive Step (2 psi).","content":"\u003cp\u003eWhen you are hit by an attack, you can use your reaction to gain a +4 bonus to AC against that attack, possibly turning it into a miss. You then teleport up to 10 feet to an unoccupied space you can see.\u003c/p\u003e"},{"title":"There and Back Again (2 psi).","content":"\u003cp\u003eAs a bonus action, you teleport up to 20 feet to an unoccupied space you can see and then move up to half your speed. At the end of your turn, you can teleport back to the spot you occupied before teleporting, unless it is now occupied or on a different plane of existence.\u003c/p\u003e"},{"title":"Transposition (3 psi).","content":"\u003cp\u003eIf you haven\u0027t moved yet on your turn, choose an ally you can see within 60 feet of you. As a bonus action, you and that creature teleport, swapping places, and your speed is reduced to 0 until the end of the turn. This ability fails and is wasted if either of you can\u0027t fit in the destination space.\u003c/p\u003e"},{"title":"Baneful Transposition (5 psi).","content":"\u003cp\u003eAs an action, choose one creature you can see within 120 feet of you. That creature must make a Wisdom saving throw. On a failed save, you and that creature teleport, swapping places. This ability fails and is wasted if either of you can\u0027t fit in the destination space.\u003c/p\u003e"},{"title":"Phantom Caravan (6 psi).","content":"\u003cp\u003eAs an action, you and up to six willing creatures of your choice that you can see within 60 feet of you teleport up to 1 mile to a spot you can see. If there isn\u0027t an open space for all the targets to occupy at the arrival point, this ability fails and is wasted.\u003c/p\u003e"},{"title":"Nomad\u0027s Gate (7 psi; conc., 1 hr.).","content":"\u003cp\u003eAs an action, you create a 5-foot cube of dim, gray light within 5 feet of you. You create an identical cube at any point of your choice within 1 mile that you have viewed within the past 24 hours. Until your concentration ends, anyone entering one of the cubes immediately teleports to the other one, appearing in an unoccupied space next to it. The teleportation fails if there is no space for the creature to appear in.\u003c/p\u003e"}]},{"group":"Nomad","title":"Third Eye","introduction":"\u003cp\u003e\u003cem\u003eNomad Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou create a third, psychic eye in your mind, which you cast out into the world. It channels thoughts and knowledge back to you, greatly enhancing your senses.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you have darkvision with a range of 60 feet. If you already have darkvision with that range or greater, increase its range by 10 feet.\u003c/p\u003e","abilities":[{"title":"Tremorsense (2 psi; conc., 1 min.).","content":"\u003cp\u003eAs a bonus action, you gain tremorsense with a radius of 30 feet, which lasts until your concentration ends.\u003c/p\u003e"},{"title":"Unwavering Eye (2 psi).","content":"\u003cp\u003eAs a bonus action, you gain advantage on Wisdom checks for 1 minute.\u003c/p\u003e"},{"title":"Piercing Sight (3 psi; conc., 1 min.).","content":"\u003cp\u003eAs a bonus action, you gain the ability to see through objects that are up to 1 foot thick within 30 feet of you. This sight lasts until your concentration ends.\u003c/p\u003e"},{"title":"Truesight (5 psi; conc., 1 min.).","content":"\u003cp\u003eAs a bonus action, you gain truesight with a radius of 30 feet, which lasts until your concentration ends.\u003c/p\u003e"}]},{"group":"Wu-Jen","title":"Mastery of Air","introduction":"\u003cp\u003e\u003cem\u003eWu Jen Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou become one with the power of elemental air.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you take no falling damage, and you ignore difficult terrain when walking.\u003c/p\u003e","abilities":[{"title":"Wind Step (1-7 psi).","content":"\u003cp\u003eAs part of your move on your turn, you can fly up to 20 feet for each psi point spent. If you end flight in the air, you fall unless something else holds you aloft.\u003c/p\u003e"},{"title":"Wind Stream (1-7 psi).","content":"\u003cp\u003eAs an action, you create a line of focused air that is 30 feet long and 5 feet wide. Each creature in that area must make a Strength saving throw, taking 1d8 bludgeoning damage per psi point spent and being knocked prone on a failed save, or half as much damage on a successful one.\u003c/p\u003e"},{"title":"Cloud of Air (3 psi; conc., 10 min.).","content":"\u003cp\u003eAs a bonus action, you seize control of the air around you to create a protective veil. Until your concentration ends, attack rolls against you have disadvantage, and when a creature you can see misses you with a melee attack, you can use your reaction to force the creature to repeat the attack roll against itself.\u003c/p\u003e"},{"title":"Wind Form (5 psi; conc., 10 min.).","content":"\u003cp\u003eAs a bonus action, you gain a flying speed of 60 feet, which lasts until your concentration ends.\u003c/p\u003e"},{"title":"Misty Form (6 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, your body becomes like a misty cloud until your concentration ends. In this form, you gain resistance to bludgeoning, piercing, and slashing damage, and you can\u0027t take actions other than the Dash action. You can pass through openings that are no more than 1 inch wide without squeezing.\u003c/p\u003e"},{"title":"Animate Air (7 psi; conc., 1 hr.).","content":"\u003cp\u003eAs an action, you cause an Air Elemental to appear in an unoccupied space you can see within 120 feet of you. The elemental lasts until your concentration ends, and it obeys your verbal commands. In combat, roll for its initiative, and choose its behavior during its turns. When this effect ends, the elemental disappears. See the Monster Manual for its stat block.\u003c/p\u003e"}]},{"group":"Wu-Jen","title":"Mastery of Fire","introduction":"\u003cp\u003e\u003cem\u003eWu Jen Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou align your mind with the energy of elemental fire.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you gain resistance to fire damage, and you gain a +2 bonus to rolls for damage.\u003c/p\u003e","abilities":[{"title":"Combustion (1-7 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, choose one creature or object you can see within 120 feet of you. The target must make a Constitution saving throw. On a failed save, the target takes 1d10 fire damage per psi point spent, and it catches on fire; taking 1d6 fire damage at the end of each of its turns until your concentration ends or until it or a creature adjacent to it extinguishes the flames with an action. On a successful save, the target takes half as much damage and doesn\u0027t catch on fire.\u003c/p\u003e"},{"title":"Rolling Flame (3 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, you create fire in a 20-foot-by-20-foot cube within 5 feet of you. The fire lasts until your concentration ends. Any creature in that area when you use this ability and any creature that then ends its turn there takes 5 fire damage.\u003c/p\u003e"},{"title":"Detonation (5 psi).","content":"\u003cp\u003eAs an action, you create a fiery explosion at a point you can see within 120 feet of you. Each creature in a 20-foot-radius sphere centered on that point must make a Constitution saving throw, taking 7d6 fire damage on a failed save, or half as much damage on a successful one.\u003c/p\u003e"},{"title":"Fire Form (5 psi; conc., 1 min.).","content":"\u003cp\u003eAs a bonus action, you become wrapped in flames until your concentration ends. Any creature that ends its turn within 5 feet of you takes 3d6 fire damage.\u003c/p\u003e"},{"title":"Animate Fire (7 psi; conc., 1 hr.).","content":"\u003cp\u003eAs an action, you cause a Fire Elemental to appear in an unoccupied space you can see within 120 feet of you. The elemental lasts until your concentration ends, and it obeys your verbal commands. In combat, roll for its initiative, and choose its behavior during its turns. When this effect ends, the elemental disappears. See the Monster Manual for its stat block.\u003c/p\u003e"}]},{"group":"Wu-Jen","title":"Mastery of Force","introduction":"\u003cp\u003e\u003cem\u003eWu Jen Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eAs a student of psionic power, you perceive the potential energy that flows through all things. You reach out with your mind, transforming the potential into the actual. Objects and creatures move at your command.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you have advantage on Strength checks.\u003c/p\u003e","abilities":[{"title":"Push (1-7 psi).","content":"\u003cp\u003eAs an action, choose one creature you can see within 60 feet of you. The target must make a Strength saving throw. On a failed save, it takes 1d8 force damage per psi point spent and is pushed up to 5 feet per point spent in a straight line away from you. On a successful save, it takes half as much damage.\u003c/p\u003e"},{"title":"Move (2-7 psi).","content":"\u003cp\u003eChoose one object you can see within 60 feet of you that isn\u0027t being worn or carried by another creature and that isn\u0027t secured in place. It can\u0027t be larger than 20 feet on a side, and its maximum weight depends on the psi points spent on this ability, as shown below.\u003c/p\u003e\r\n          \u003cp\u003eAs an action, you move the object up to 60 feet, and you must keep the object within sight during this movement. If the object ends this movement in the air, it falls. If the object would fall on a creature, the creature must succeed on a DC 10 Dexterity saving throw or take damage as listed on the table below.\u003c/p\u003e\r\n\r\n          \u003cdiv class=\"table-wrap feature-table\"\u003e\r\n            \u003ctable\u003e\r\n              \u003cthead\u003e\r\n                \u003ctr\u003e\u003cth\u003ePsi Spent\u003c/th\u003e\u003cth\u003eMaximum Weight\u003c/th\u003e\u003cth\u003eBludgeoning Damage\u003c/th\u003e\u003c/tr\u003e\r\n              \u003c/thead\u003e\r\n              \u003ctbody\u003e\r\n                \u003ctr\u003e\u003ctd\u003e2\u003c/td\u003e\u003ctd\u003e25 lbs.\u003c/td\u003e\u003ctd\u003e2d6\u003c/td\u003e\u003c/tr\u003e\r\n                \u003ctr\u003e\u003ctd\u003e3\u003c/td\u003e\u003ctd\u003e50 lbs.\u003c/td\u003e\u003ctd\u003e4d6\u003c/td\u003e\u003c/tr\u003e\r\n                \u003ctr\u003e\u003ctd\u003e5\u003c/td\u003e\u003ctd\u003e250 lbs.\u003c/td\u003e\u003ctd\u003e6d6\u003c/td\u003e\u003c/tr\u003e\r\n                \u003ctr\u003e\u003ctd\u003e6\u003c/td\u003e\u003ctd\u003e500 lbs.\u003c/td\u003e\u003ctd\u003e7d6\u003c/td\u003e\u003c/tr\u003e\r\n                \u003ctr\u003e\u003ctd\u003e7\u003c/td\u003e\u003ctd\u003e1000 lbs.\u003c/td\u003e\u003ctd\u003e8d6\u003c/td\u003e\u003c/tr\u003e\r\n              \u003c/tbody\u003e\r\n            \u003c/table\u003e\r\n          \u003c/div\u003e"},{"title":"Inertial Armor (2 psi).","content":"\u003cp\u003eAs an action, you sheath yourself in an intangible field of magical force. For 8 hours, your base AC is 14 + your Dexterity modifier, and you gain resistance to force damage. This effect ends if you are wearing or don armor.\u003c/p\u003e"},{"title":"Telekinetic Barrier (3 psi; conc., 10 min.).","content":"\u003cp\u003eAs an action, you create a transparent wall of telekinetic energy, at least one portion of which must be within 60 feet of you. The wall is 40 feet long, 10 feet high, and 1 inch thick. The wall lasts until your concentration ends. Each 10-foot section of the wall has an AC of 10 and 10 hit points.\u003c/p\u003e"},{"title":"Graps (3 psi; conc., 1 min.).","content":"\u003cp\u003eYou attempt to grasp a creature in telekinetic energy and hold it captive. As an action, choose one creature you can see within 60 feet of you. The target must succeed on a Strength saving throw or be grappled by you until your concentration ends or until the target leaves your reach, which is 60 feet for this grapple.\u003c/p\u003e\r\n          \u003cp\u003eThe grappled target can escape by succeeding on a Strength (Athletics) or Dexterity (Acrobatics) check contested by your psionic ability plus your proficiency bonus. When a target attempts to escape in this way, you can spend psi points to boost your check, abiding by your psi limit. You gain a +1 bonus per psi point spent.\u003c/p\u003e\r\n          \u003cp\u003eWhile a target is grappled in this manner, you create one of the following effects as an action:\u003c/p\u003e\r\n          \u003cul\u003e\r\n            \u003cli\u003e\u003cstrong\u003eCrush\u003c/strong\u003e (1-7 psi). The target takes 1d6 bludgeoning damage per psi point spent.\u003c/li\u003e\r\n            \u003cli\u003e\u003cstrong\u003eMove\u003c/strong\u003e (1-7 psi). You move the target up to 5 feet per psi point spent. You can move it in the air and hold it there. If it falls, the grapple ends.\u003c/li\u003e\r\n          \u003c/ul\u003e"}]},{"group":"Wu-Jen","title":"Mastery of Ice","introduction":"\u003cp\u003e\u003cem\u003eWu Jen Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou master the power of ice, shaping it to meet your demands.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you have resistance to cold damage.\u003c/p\u003e","abilities":[{"title":"Ice Spike (1-7 psi).","content":"\u003cp\u003eAs an action, you hurl a mote of ice at one creature you can see within 120 feet of you. The target must make a Dexterity saving throw. On a failed save, the target takes 1d8 cold damage per psi point spent and has its speed halved until the start of your next turn. On a successful save, the target takes half as much damage.\u003c/p\u003e"},{"title":"Ice Sheet (2 psi).","content":"\u003cp\u003eAs an action, choose a point on the ground you can see within 60 feet of you. The ground in a 20-foot radius centered on that point becomes covered in ice for 10 minutes. It is difficult terrain, and any creature that moves more than 10 feet on it must succeed on a Dexterity saving throw or fall prone. If the surface is sloped, a creature that falls prone in the area immediately slides to the bottom of the slope.\u003c/p\u003e"},{"title":"Frozen Sanctuary (3 psi).","content":"\u003cp\u003eAs a bonus action, you sheath yourself with icy resilience. You gain 20 temporary hit points.\u003c/p\u003e"},{"title":"Frozen Rain (5 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, choose a point you can see within 120 feet of you. The air in a 20-foot-radius sphere centered on that point becomes deadly cold and saturated with moisture. Each creature in that area must make a Constitution saving throw. On a failed save, a target takes 6d6 cold damage, and its speed is reduced to 0 until your concentration ends. On a successful save, a target takes half as much damage.\u003c/p\u003e"},{"title":"Ice Barrier (6 psi; conc., 10 min.).","content":"\u003cp\u003eAs an action, you create a wall of ice, at least one portion of which must be within 60 feet of you. The wall is 60 feet long, 15 feet high, and 1 foot thick. The wall lasts until your concentration ends. Each 10-foot section of the wall has AC 12 and 30 hit points. A creature that damages the wall with a melee attack takes cold damage equal to the damage the creature dealt to the wall.\u003c/p\u003e"}]},{"group":"Wu-Jen","title":"Mastery of Light and Darkness","introduction":"\u003cp\u003e\u003cem\u003eWu Jen Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou claim dominion over light and darkness with your mind.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, natural and magical darkness within 30 feet of you has no effect on your vision.\u003c/p\u003e","abilities":[{"title":"Darkness (1-7 psi).","content":"\u003cp\u003eAs an action, you create an area of magical darkness, which foils darkvision. Choose a spot you can see within 60 feet of you. Magical darkness radiates from that point in a sphere with a 10-foot radius per psi point spent on this ability. The light produced by spells of 2nd level or less is suppressed in this area.\u003c/p\u003e"},{"title":"Light (2 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, an object you touch radiates light in a 20-foot radius and dim light for an additional 20 feet. The light lasts until your concentration ends. Alternatively, a creature you touch has light radiating from it in the same manner if it fails a Dexterity saving throw. While lit in this manner, it can\u0027t hide, and attack rolls against it give disadvantage.\u003c/p\u003e"},{"title":"Shadow Beasts (3 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, you cause two Shadows to appear in unoccupied spaces you can see within 60 feet of you. The Shadows last until your concentration ends, and they obey your verbal commands. In combat, roll for their initiative, and choose their behavior during their turns. When this effect ends, the shadows disappear. See the Monster Manual for their stat block.\u003c/p\u003e"},{"title":"Radiant Beam (5 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, you project a beam of light at one creature you can see within 60 feet of you. The target must make a Dexterity saving throw. On a failed save, it takes 6d6 radiant damage and is blinded until your concentration ends. On a successful save, it takes half as much damage. A blinded target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.\u003c/p\u003e\r\n          \u003cp\u003eYou can increase this effect\u0027s damage by 1d6 per each additional psi point spent on it.\u003c/p\u003e"}]},{"group":"Wu-Jen","title":"Mastery of Water","introduction":"\u003cp\u003e\u003cem\u003eWu Jen Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYour mind becomes one with elemental water, attuning your thoughts to its ebb and flow.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you have a swimming speed equal to your walking speed, and you can breathe underwater.\u003c/p\u003e","abilities":[{"title":"Desiccate (1-7 psi).","content":"\u003cp\u003eAs an action, choose one creature you can see within 60 feet of you. The target must make a Constitution saving throw, taking 1d10 necrotic damage per psi point spent on this ability, or half as much damage on a successful one.\u003c/p\u003e"},{"title":"Water Grasp (2 psi).","content":"\u003cp\u003eAs an action, you unleash a wave that surges forth and then retreats to you like the rising tide. You create a wave in a 20-foot-by-20-foot square. At least some portion of the square\u0027s border must be within 5 feet of you. Any creature in that square must make a Strength saving throw. On a failed save, a target takes 2d6 bludgeoning damage, is knocked prone, and is pulled up to 10 feet closer to you. On a successful save, a target takes half as much damage. You can increase this ability\u0027s damage by 1d6 per additional psi point spent on it.\u003c/p\u003e"},{"title":"Water Whip (3 psi).","content":"\u003cp\u003eAs an action, you unleash a jet of water in a line that is 60 feet long and 5 feet wide. Each creature in the line must make a Strength saving throw, taking 3d6 bludgeoning damage on a failed save, or half as much damage on a successful one. In addition, you can move each target that fails its saving throw to any unoccupied space touching the line. You can increase this ability\u0027s damage by 1d6 per additional psi point spent on it.\u003c/p\u003e"},{"title":"Water Breathing (5 psi).","content":"\u003cp\u003eAs an action, you grant yourself and up to ten willing creatures you can see within 60 feet of you the ability to breathe underwater for the next 24 hours.\u003c/p\u003e"},{"title":"Water Sphere (6 psi; conc., 1 min.).","content":"\u003cp\u003eAs an action, you cause a sphere of water to form around a creature. Choose one creature you can see within 60 feet of you. The target must make a Dexterity saving throw. On a failed save, it becomes trapped in the sphere of water until your concentration ends. While the target is trapped, its speed is halved, it suffers disadvantage on attack rolls, and it can\u0027t see anything more than 10 feet away from it. However, attack rolls against it also suffer disadvantage. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a successful one.\u003c/p\u003e"},{"title":"Animate Water (7 psi; conc., 1 hr.).","content":"\u003cp\u003eAs an action, you cause a Water Elemental to appear in an unoccupied space you can see within 120 feet of you. The elemental lasts until your concentration ends, and it obeys your verbal commands. In combat, roll for its initiative, and choose its behavior during its turns. When this effect ends, the elemental disappears. See the Monster Manual for its stat block.\u003c/p\u003e"}]},{"group":"Wu-Jen","title":"Mastery of Weather","introduction":"\u003cp\u003e\u003cem\u003eWu Jen Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYour mind reaches into the sky, reshaping the stuff of storms to serve your needs.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you have resistance to lightning and thunder damage.\u003c/p\u003e","abilities":[{"title":"Cloud Steps (1-7 psi; conc., 10 min.).","content":"\u003cp\u003eAs an action, you conjure forth clouds to create a solid, translucent staircase that lasts until your concentration ends. The stairs form a spiral that fills a 10-foot-by-10-foot area and reaches upward 20 feet per psi point spent.\u003c/p\u003e"},{"title":"Hungry Lightning (1-7 psi).","content":"\u003cp\u003eAs an action, you lash out at one creature you can see within 60 feet of you with tendrils of lightning. The target must make a Dexterity saving throw, with disadvantage if it is wearing heavy armor. The target takes 1d8 lightning damage per psi point spent on a failed save, or half as much damage on a successful one.\u003c/p\u003e"},{"title":"Wall of Clouds (2 psi; conc., 10 min.).","content":"\u003cp\u003eAs an action, you create a wall of clouds, at least one portion of which must be within 60 feet of you. The wall is 60 feet long, 15 feet high, and 1 foot thick. The wall lasts until your concentration ends. Creatures can pass through it without hindrance, but the wall blocks vision.\u003c/p\u003e"},{"title":"Whirlwind (2 psi).","content":"\u003cp\u003eAs an action, choose a point you can see within 60 feet of you. Winds howl in a 20-foot-radius sphere centered on that point. Each creature in the sphere must succeed on a Strength saving throw or take 1d6 bludgeoning damage and be moved to an unoccupied space of your choice within the sphere. Any loose object in the sphere is moved to an unoccupied space of your choice within it if the object weighs no more than 100 pounds.\u003c/p\u003e"},{"title":"Lightning Leap (5 psi).","content":"\u003cp\u003eAs an action, you let loose a line of lightning that is 60 feet long and 5 feet wide. Each creature in the line must make a Dexterity saving throw, taking 6d6 lightning damage on a failed save, or half as much damage on a successful one. You can then teleport to an unoccupied space touched by the line.\u003c/p\u003e\r\n          \u003cp\u003eYou can increase this ability\u0027s damage by 1d6 per additional psi point spent on it.\u003c/p\u003e"},{"title":"Wall of Thunder (6 psi; conc., 10 min.).","content":"\u003cp\u003eAs an action, you create a wall of thunder, at least one portion of which must be within 60 feet of you. The wall is 60 feet long, 15 feet high, and 1 foot thick. The wall lasts until your concentration ends. Every foot moved through the wall costs 1 extra foot of movement. When a creature moves into the wall\u0027s space for the first time on a turn or starts its turn there, that creature must succeed on a Strength saving throw, or it takes 6d6 thunder damage, is pushed in a straight line up to 30 feet away from the wall, and is knocked prone.\u003c/p\u003e"},{"title":"Thunder Clap (7 psi).","content":"\u003cp\u003eAs an action, choose a point you can see within 60 feet of you. Thunder energy erupts in a 20-foot-radius sphere centered on that point. Each creature in that area must make a Constitution saving throw. On a failed save, a target takes 8d6 thunder damage, and it is stunned until the end of your next turn. On a successful save, a target takes half as much damage.\u003c/p\u003e"}]},{"group":"Wu-Jen","title":"Mastery of Wood and Earth","introduction":"\u003cp\u003e\u003cem\u003eWu Jen Discipline\u003c/em\u003e\u003c/p\u003e\r\n          \u003cp\u003eYou attune your mind to seize control of wood and earth.\u003c/p\u003e\r\n          \u003cp\u003e\u003cstrong\u003ePsychic Focus.\u003c/strong\u003e While focused on this discipline, you have a +1 bonus to AC.\u003c/p\u003e","abilities":[{"title":"Animate Weapon (1-7 psi).","content":"\u003cp\u003eAs an action, your mind seizes control of a one-handed melee weapon you\u0027re holding. The weapon flies toward one creature you can see within 30 feet of you and makes a one-handed melee weapon attack against it, using your discipline attack modifier for the attack and damage rolls. On a hit, the weapon deals its normal damage, plus an extra 1d10 force damage per psi point spent on this ability. The weapon returns to your grasp after it attacks.\u003c/p\u003e"},{"title":"Warp Weapon (2 psi).","content":"\u003cp\u003eAs an action, choose one non-Relic weapon held by one creature you can see within 60 feet of you. That creature must succeed on a Strength saving throw, or the chosen weapon can\u0027t be used to attack until the end of your next turn.\u003c/p\u003e"},{"title":"Warp Armor (3 psi).","content":"\u003cp\u003eAs an action, choose one non-Relic suit of armor worn by one creature you can see within 60 feet of you. That creature must succeed on a Constitution saving throw, or the creature\u0027s AC becomes 10 + its Dexterity modifier until the end of your next turn.\u003c/p\u003e"},{"title":"Wall of Wood (3 psi; conc., 1 hr.).","content":"\u003cp\u003eAs an action, you create a wall of wood at least one portion of which must be within 60 feet of you. The wall is 60 feet long, 15 feet high, and 1 foot thick. The wall lasts until your concentration ends. Each 5-foot-wide section of the wall has AC 12 and 100 hit points. Breaking one section creates a 5-foot by 5-foot hole in it, but the wall otherwise remains intact.\u003c/p\u003e"},{"title":"Armored Form (6 psi; conc., 1 min.).","content":"\u003cp\u003eAs a bonus action, you gain resistance to bludgeoning, piercing, and slashing damage, which lasts until your concentration ends.\u003c/p\u003e"},{"title":"Animate Earth (7 psi; conc., 1 hr.).","content":"\u003cp\u003eAs an action, you cause an Earth Elemental to appear in an unoccupied space you can see within 120 feet of you. The elemental lasts until your concentration ends, and it obeys your verbal commands. In combat, roll for its initiative, and choose its behavior during its turns. When this effect ends, the elemental disappears. See the Monster Manual for its stat block.\u003c/p\u003e"}]}];
